import math

def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    # Check the final sum S_n first. If it's a square, n cannot be cool.
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return False, "Total sum is a square"

    # Backtracking search
    def solve(current_sum, used_mask, length):
        if length == n:
            # We already checked total_sum, so if we reached here, it's valid.
            return True

        # Try placing the next element x
        for x in range(1, n + 1):
            if not (used_mask & (1 << (x - 1))):
                next_sum = current_sum + x

                # Check prefix sum condition
                if not is_square(next_sum):
                    new_mask = used_mask | (1 << (x - 1))
                    if solve(next_sum, new_mask, length + 1):
                        return True
        return False

    # Start the search
    if solve(0, 0, 0):
        return True, "Found permutation"
    else:
        return False, "No permutation found"

# Test for n=1 to n=15
results = {}
for n in range(1, 16):
    cool, reason = is_cool(n)
    results[n] = cool

print("N | Cool Status")
print("-" * 20)
for n in range(1, 16):
    status = "Yes" if results[n] else "No"
    print(f"{n} | {status}")

print("\nList of cool integers found (N=1 to 15):")
cool_integers = [n for n, is_cool_status in results.items() if is_cool_status]
print(cool_integers)

